            {isReadOnly ? (
              <ComposeAttachments
                imageUris={media.images}
                onRemoveImage={media.removeImage}
                audioUris={media.audios}
                onRemoveAudio={media.removeAudio}
                attachments={media.attachments}
                onRemoveAttachment={media.removeAttachment}
                readOnly
