import type { Attachment } from "@/shared/types";

export function parseUris(json: string | null | undefined): string[] {
  if (!json) return [];
  try {
    const parsed = JSON.parse(json) as unknown;
    if (Array.isArray(parsed)) {
      return parsed.filter((uri): uri is string => typeof uri === "string");
    }
    return [];
  } catch {
    return [];
  }
}

/** Parses a stored `attachments` column, tolerating malformed rows from older or corrupted data. */
export function parseAttachments(json: string | null | undefined): Attachment[] {
  if (!json) return [];
  try {
    const parsed = JSON.parse(json) as unknown;
    if (!Array.isArray(parsed)) return [];
    return parsed
      .filter((item): item is Record<string, unknown> => typeof item === "object" && item !== null)
      .map((item) => ({
        uri: typeof item.uri === "string" ? item.uri : "",
        name: typeof item.name === "string" && item.name ? item.name : "File",
        mime: typeof item.mime === "string" ? item.mime : undefined,
        size: typeof item.size === "number" ? item.size : undefined,
      }))
      .filter((attachment) => attachment.uri.length > 0);
  } catch {
    return [];
  }
}
import { migrateToV1 } from "./migrations/v1.ts";

export interface SchemaDatabase {
  execAsync(source: string): Promise<void>;
  getFirstAsync<T>(source: string, ...params: unknown[]): Promise<T | null>;
  getAllAsync<T>(source: string, ...params: unknown[]): Promise<T[]>;
  withTransactionAsync(task: () => Promise<void>): Promise<void>;
}

interface DatabaseMigration {
  version: number;
  up: (db: SchemaDatabase, schema: string) => Promise<void>;
}

/**
 * Add one immutable file per forward schema change, then register it here.
 * Never edit a migration that has shipped or renumber an existing version.
 */
const MIGRATIONS: readonly DatabaseMigration[] = [{ version: 1, up: migrateToV1 }];

export const DATABASE_SCHEMA_VERSION = MIGRATIONS[MIGRATIONS.length - 1].version;

async function readSchemaVersion(db: SchemaDatabase, schema: string): Promise<number> {
  const result = await db.getFirstAsync<{ user_version: number }>(`PRAGMA ${schema}.user_version`);
  return result?.user_version ?? 0;
}

async function applyMigrations(
  db: SchemaDatabase,
  currentVersion: number,
  minimumVersion: number,
  schema: string
): Promise<void> {
  if (currentVersion < minimumVersion) {
    throw new Error(`Unsupported database version (${currentVersion}).`);
  }
  if (currentVersion > DATABASE_SCHEMA_VERSION) {
    throw new Error(`Unsupported database version (${currentVersion}). Please update OpenLog.`);
  }

  const pending = MIGRATIONS.filter((migration) => migration.version > currentVersion);
  for (const migration of pending) {
    await db.withTransactionAsync(async () => {
      await migration.up(db, schema);
      await db.execAsync(`PRAGMA ${schema}.user_version = ${migration.version}`);
    });
  }
}

/** Opens a fresh database at v1, or moves an existing supported database forward. */
export async function migrateDatabaseSchema(db: SchemaDatabase): Promise<void> {
  await applyMigrations(db, await readSchemaVersion(db, "main"), 0, "main");
}

export async function initializeDatabaseSchema(db: SchemaDatabase): Promise<void> {
  await db.execAsync(`
    PRAGMA journal_mode = WAL;
    PRAGMA synchronous = NORMAL;
    PRAGMA busy_timeout = 5000;
    PRAGMA foreign_keys = OFF;
  `);

  await migrateDatabaseSchema(db);

  // Foreign keys stay off until migrations finish: the pragma is a no-op
  // inside a transaction, and enabled constraints block table rebuilds.
  await db.execAsync("PRAGMA foreign_keys = ON;");

  await initializeSearchIndex(db);
}

export async function recreateSearchIndex(db: SchemaDatabase, schema: string): Promise<void> {
  await db.execAsync(`
    DROP TRIGGER IF EXISTS ${schema}.entries_fts_ai;
    DROP TRIGGER IF EXISTS ${schema}.entries_fts_ad;
    DROP TRIGGER IF EXISTS ${schema}.entries_fts_au;
    DROP TABLE IF EXISTS ${schema}.entries_fts;
    CREATE VIRTUAL TABLE ${schema}.entries_fts USING fts5(
      text,
      location,
export interface EntryLocation {
  latitude: number;
  longitude: number;
  /** City or town, state, country — e.g. "Austin, Texas, United States". */
  name?: string;
}

/** A generic attached document (PDF, spreadsheet, video, anything) kept alongside an entry. */
export interface Attachment {
  /** Media reference: the stored filename on inputs, resolved to a live file URI on read. */
  uri: string;
  /** Original filename shown to the user, e.g. "Invoice.pdf". */
  name: string;
  mime?: string;
  size?: number;
}

export const TAG_COLOR_IDS = ["clay", "amber", "sage", "violet", "teal", "rose"] as const;
export type TagColorId = (typeof TAG_COLOR_IDS)[number];

export interface Tag {
  id: string;
  name: string;
  colorId: TagColorId;
}

/** A tag with how many entries carry it, for browsing and choosing tags. */
export interface TagSummary extends Tag {
  entryCount: number;
}

export interface Entry {
  id: string;
  createdAt: number;
  updatedAt: number;
  text?: string;
  /** Live file URIs resolved from stored filenames; SQLite persists bare filenames only. */
  images: string[];
  audios: string[];
  attachments: Attachment[];
  tags: Tag[];
  location?: EntryLocation;
}

export interface NewEntryInput {
  text?: string | null;
  images?: string[];
  audios?: string[];
  attachments?: Attachment[];
  tagIds?: string[];
  createdAt?: number;
  location?: EntryLocation | null;
}

export interface UpdateEntryInput {
  /** `undefined` keeps the stored text; `null` clears it. */
  text?: string | null;
  images?: string[];
  audios?: string[];
  attachments?: Attachment[];
  tagIds?: string[];
  createdAt?: number;
  location?: EntryLocation | null;
}

export interface EntrySearchResult {
  entry: Entry;
  /** Context around the first text match; empty when the entry has no text. Match ranges are wrapped in `\u0001 … \u0002` markers. */
  snippet: string;
  /** Context around a location-name match; empty when the entry has no location. Same marker convention. */
  locationSnippet: string;
}

