import {
  SourceSans3_400Regular,
  SourceSans3_500Medium,
  SourceSans3_600SemiBold,
  useFonts,
} from "@expo-google-fonts/source-sans-3";
import { useEffect, useState } from "react";
import { useColorScheme } from "react-native";
import { getBiometricLockEnabled } from "@/services/auth";
import { getAllUserPreferences } from "@/services/db/settings";
import { fontManager } from "@/services/fonts";
import { logDevWarning, reportError } from "@/shared/utils/devLog";
import { DEFAULT_PREFERENCES, resolveTheme, resolveThemeMode, type UserPreferences } from "@/theme";

export interface AppBootstrapState {
  ready: boolean;
  preferences: UserPreferences;
  resolvedMode: "light" | "dark";
  backgroundColor: string;
  userName: string | null;
  onboardingCompleted: boolean;
}

/** Loads fonts, preferences, profile, and the device-bound lock state before the first interactive screen. */
export function useAppBootstrap(): AppBootstrapState {
  const systemScheme = useColorScheme();
  const [preferences, setPreferences] = useState<UserPreferences | null>(null);
  const [userName, setUserName] = useState<string | null>(null);
  const [onboardingCompleted, setOnboardingCompleted] = useState(false);
  const [profileLoaded, setProfileLoaded] = useState(false);
  const [fontsLoaded, fontError] = useFonts({
    SourceSans3_400Regular,
    SourceSans3_500Medium,
    SourceSans3_600SemiBold,
    "BricolageGrotesque-Bold": require("../../../assets/fonts/BricolageGrotesque-Bold.ttf"),
  });

  useEffect(() => {
    let active = true;

    // The device-bound lock resolves here so the lock gate mounts with the correct armed state.
    const loadPreferences = () =>
      Promise.all([getAllUserPreferences(), getBiometricLockEnabled()])
        .then(async ([data]) => {
          if (!active) return;
          setUserName(data.userName);
          setOnboardingCompleted(data.onboardingCompleted);
          setPreferences(data.preferences);

          const selectedFont = data.preferences.appearance.fontFamily;
          if (selectedFont && selectedFont !== "Source Sans 3") {
            // Bounded load attempt on startup so app boots quickly even if offline or slow
            try {
              await Promise.race([
                fontManager.load(selectedFont),
                new Promise((resolve) => setTimeout(resolve, 2000)),
              ]);
            } catch (error) {
              logDevWarning("bootstrap:fontLoad", error);
            }
          }
        })
        .catch((error) => {
          reportError("bootstrap:loadPreferences", error);
          if (active) {
            setPreferences(DEFAULT_PREFERENCES);
          }
        })
        .finally(() => {
          if (active) setProfileLoaded(true);
        });

    void loadPreferences();

    return () => {
      active = false;
    };
  }, []);

  const effectivePreferences = preferences ?? DEFAULT_PREFERENCES;

